import{_ as a,o as e,c as t,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const P=JSON.parse('{"title":"CMOS电路设计基础知识","description":"","frontmatter":{},"headers":[],"relativePath":"notes/《CMOS电路设计基础知识》学习笔记/01-CMOS电路设计基础知识.md","filePath":"notes/《CMOS电路设计基础知识》学习笔记/01-CMOS电路设计基础知识.md","lastUpdated":1794547538000}'),o={name:"notes/《CMOS电路设计基础知识》学习笔记/01-CMOS电路设计基础知识.md"};function d(s,p,n,l,i,c){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="cmos电路设计基础知识" tabindex="-1">CMOS电路设计基础知识 <a class="header-anchor" href="#cmos电路设计基础知识" aria-label="Permalink to &quot;CMOS电路设计基础知识&quot;">​</a></h1><h2 id="一芯片与集成电路的定义" tabindex="-1">一、芯片与集成电路的定义 <a class="header-anchor" href="#一芯片与集成电路的定义" aria-label="Permalink to &quot;一、芯片与集成电路的定义&quot;">​</a></h2><p>芯片的英文名叫 chip。</p><p>芯片是一个比较笼统的称谓。</p><p>对电子设备来说，它藏在内部，又非常重要，相当于汽车的发动机、人的心脏，所以叫&quot;芯&quot;；</p><p>从形态上看，它是一片一片的片状结构，所以叫&quot;片&quot;。</p><p>合起来就是芯片。</p><p>芯片经过设计、制造、封装、测试，形成可以直接使用的产品形态。</p><p>强调用途的时候，更多采用&quot;某某芯片&quot;的叫法，比如 CPU 芯片、AI 芯片、基带芯片，这是从应用的角度给出的称谓。</p><p>芯片的一种定义：包含了一个或者多个集成电路，能够实现某种特定功能的通用半导体元件产品。</p><p>或者说，芯片是半导体元件产品的统称。</p><p>芯片、集成电路这些词经常混用。</p><p>本质上芯片就是集成电路（Integrated Circuit），两者可以划等号。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794304522438-fb57d641-92fe-4c1f-86f4-a38750158df0.svg" alt="半导体、芯片、集成电路三个圆交叠"></p><p><em>蓝色是半导体，左下是芯片，右下是集成电路。</em></p><p>集成电路：通过特定技术，将晶体管、电阻、电容、二极管等电子元件集成在单一基板上，形成的一种微型电路。</p><p>半导体集成电路：如果基板采用半导体材料，比如最常用的硅，或者说集成电路由半导体材料晶圆制造而来，就属于半导体集成电路。</p><p>传统意义上的集成电路，基本上就是指半导体集成电路。</p><p>半导体、芯片、集成电路三个词经常混用，没有很明显的界限。</p><h2 id="二半导体与集成电路的关系" tabindex="-1">二、半导体与集成电路的关系 <a class="header-anchor" href="#二半导体与集成电路的关系" aria-label="Permalink to &quot;二、半导体与集成电路的关系&quot;">​</a></h2><p>半导体包括集成电路、分立器件、光电子器件、传感器。后面三个统称为 O-S-D。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794304523157-b83fd429-8372-4016-926f-9136b3dc427e.svg" alt="半导体分出集成电路与 O-S-D 两支"></p><p><em>O-S-D 下分光电子器件、传感器、分立器件。</em></p><p>集成电路和另外三个的主要区别在于集成度：集成电路的晶体管数量远远大于分立器件、光电子器件和传感器。</p><p>另外，衬底材料也不一样。集成电路用的是硅材料，其他元器件一般不是硅材料。</p><p>目前，光电子器件、分立器件和传感器的市场规模加在一起，仅占到全球半导体市场规模的 10% 左右。</p><p>所以，集成电路是整个半导体产业最重要的组成部分。</p><h2 id="三按功能分类" tabindex="-1">三、按功能分类 <a class="header-anchor" href="#三按功能分类" aria-label="Permalink to &quot;三、按功能分类&quot;">​</a></h2><p>芯片的种类非常多。</p><p>按功能分，通常分为计算芯片、存储芯片、通信芯片、感知芯片、能源芯片以及接口芯片。</p><p>这是按大类分，每个大类里面又有很多小类。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794385283888-7bf3bfc3-4c5d-4428-8010-46fbb90565bd.svg" alt="按功能划分的芯片大类、小类与功能表"></p><p>计算芯片里包括中央处理器 CPU、图形处理器 GPU，还有 DPU、NPU、APU 这类用于数据处理、神经网络计算以及音频处理芯片。</p><p>存储芯片里有 RAM、ROM。</p><p>通信芯片，里面有 5G 基带/射频芯片、Wi-Fi 芯片、蓝牙芯片，还有以太网芯片。</p><p>射频芯片主要实现蜂窝移动通信功能，Wi-Fi 芯片用于实现无线局域网的通信功能。</p><p>通信芯片目前基本上被国际大厂垄断，比如高通、博通、TI、英特尔。</p><p>国内头部企业对通信类芯片的需求度比较高，一般也会有一些芯片自研，但市面上通用的射频类芯片比较少。</p><p>其他领域，比如感知类的环境传感器芯片、图像传感器芯片，还有电源管理、模数转换类的芯片，也会对场仿真工具有些需求，但需求度没有那么高。</p><p>能源芯片里的数模转换芯片，大多数不涉及射频，比较前沿的射频类数模转换芯片，因为涉及高频，可能也会用到场仿真工具。</p><h2 id="四按半导体材料分类" tabindex="-1">四、按半导体材料分类 <a class="header-anchor" href="#四按半导体材料分类" aria-label="Permalink to &quot;四、按半导体材料分类&quot;">​</a></h2><p>另一种分类方式是按半导体材料。芯片可以分为第一代半导体、第二代半导体和第三代半导体。</p><table><thead><tr><th>代际</th><th>类别</th><th>代表材料</th><th>优点</th><th>应用领域</th></tr></thead><tbody><tr><td rowspan="2">第一代半导体</td><td rowspan="2">单元素半导体材料</td><td>硅(Si)</td><td>储量丰富，价格低</td><td>消费电子、通信、先进制程芯片等</td></tr><tr><td>锗(Ge)</td><td>电子迁移率、空间迁移率高</td><td>空间卫星太阳能电池面板</td></tr><tr><td rowspan="2">第二代半导体</td><td rowspan="2">III-V族化合物半导体材料</td><td>砷化镓(GaAs)</td><td>光电性能好、耐热、抗辐射</td><td>显示器、射频模块</td></tr><tr><td>磷化铟(InP)</td><td>导热性好、光电转换效率高</td><td>光通信</td></tr><tr><td rowspan="2">第三代半导体</td><td rowspan="2">宽禁带半导体</td><td>氮化镓(GaN)</td><td>耐高温、高压，大功率</td><td>充电器、高铁</td></tr><tr><td>碳化硅(SiC)</td><td>同上</td><td>电动汽车</td></tr></tbody></table><p>硅得到大规模应用，主要是因为硅储量丰富、价格很低，集成度也非常高。硅成为目前半导体工艺主流的材料，广泛用在消费电子、通信和先进制程芯片领域。</p><p>锗目前还有少量领域在使用，主要是迁移率高，性能比较好，但成本相对高一些，主要用在空间卫星、太阳能电池板。</p><p>第二代半导体是 III-V 族化合物半导体材料，比较熟悉的有砷化镓工艺，还有磷化铟。光电性能好，耐热、抗辐射，整体性能比硅基的好一点，一般用在射频模组、显示器里。</p><p>化合物没有替代硅，主要是集成度没有硅高，成本相对硅也比较高。</p><p>第三代半导体是宽禁带半导体，代表是氮化镓工艺和碳化硅，属于比较新的材料。</p><p>优点是耐高温、高压和大功率。氮化镓相比于砷化镓，能够输出的功率更大一些，一般用在充电器、高铁、充电站这类对功率要求比较高的领域。</p><h2 id="五晶体管技术演进" tabindex="-1">五、晶体管技术演进 <a class="header-anchor" href="#五晶体管技术演进" aria-label="Permalink to &quot;五、晶体管技术演进&quot;">​</a></h2><p>半导体工艺、CMOS 工艺的发展，得益于晶体管技术的推进。</p><p>1948 年，肖克利发明了结型晶体管。因为使用空穴和电子两种载流子参与导电，被称为双极结型晶体管（Bipolar Junction Transistor, BJT），有 NPN 和 PNP 两种结构。优点是工作频率高、驱动能力强；缺点是功耗大、集成度低，制造工艺比较复杂。</p><p>BJT 工艺目前在一些领域还有应用，比如对速度要求比较高的地方。</p><p>1953 年，贝尔实验室的 Ian Ross 和 George Dacey 合作，制作了世界上第一个结型场效应晶体管（Junction Field Effect Transistor, JFET）原型。JFET 工作时只需要一种载流子，因此被称为单极型晶体管。</p><p>1959 年，埃及裔科学家 Mohamed Atala 与韩裔科学家 Dawon Kahng 共同发明了 MOSFET（Metal-Oxide-Semiconductor FET，金属氧化物半导体场效应管），分为 NMOS 和 PMOS 两种类型。MOSFET 奠定了 CMOS 工艺的基础，虽然它还不是 CMOS 工艺，但 CMOS 工艺来源于它这样一种整体架构。</p><p>1967 年，姜大元和华裔科学家施敏合作，共同发明了&quot;浮栅&quot;FGMOS（Floating Gate MOSFET）结构。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794304524625-2b95ae46-f067-4519-9452-1d26ed378073.svg" alt="浮栅晶体管的剖面结构"></p><p><em>自上而下是控制栅、栅氧、浮栅、隧穿氧，两侧是源漏。</em></p><p>跟传统 MOSFET 相比，它上面多了一层栅氧和浮栅结构，相当于叠了两层。</p><p>这种结构奠定了半导体存储技术的基础，后面所有的闪存、Flash、EEPROM 都是基于这种技术制造的。存储这一块跟传统工艺不太一样。</p><p>晶体管技术的演进分两类。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794304525261-8b6e5e2c-10de-40f5-8adb-ac84ede96c0d.svg" alt="晶体管分成双极型与单极型两支"></p><p><em>双极型分 NPN、PNP，单极型分结型与绝缘栅型。</em></p><p>一类是双极型的 BJT，分 NPN 和 PNP；另一类是单极型的 FET 场效应管，一个结型的，一个 MOSFET。根据载流子不同，MOSFET 也分为耗尽型和增强型。</p><h2 id="六cmos-工艺与互补结构" tabindex="-1">六、CMOS 工艺与互补结构 <a class="header-anchor" href="#六cmos-工艺与互补结构" aria-label="Permalink to &quot;六、CMOS 工艺与互补结构&quot;">​</a></h2><p>1963 年，仙童半导体的 Frank Wanlass 和华裔科学家萨支唐首次提出了 CMOS 晶体管。</p><p>萨支唐方程对早期 CMOS 工艺的理论分析有指导作用。</p><p>他们将 PMOS 和 NMOS 组合在一起，连接成互补结构，几乎没有静态电流。CMOS 的&quot;C&quot;就是 Complementary，互补。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794460228232-b742d3a9-605f-462e-8a05-8956064f322e.svg" alt="NMOS 与 PMOS 做在同一块 p 型衬底上"></p><p><em>NMOS 做在 p 衬底，PMOS 做在 n 阱里。</em></p><p>图里是做在 P Substrate 上的，上面有一个 NMOS 晶体管，也有一个 PMOS 晶体管。NMOS 是 N 型沟道，可以直接做在 P 型衬底上；PMOS 是 P 型沟道，不能直接做在 P Substrate 上，需要额外做一个 n 阱。</p><p>这种互补结构最大的<strong>特点</strong>是功耗远低于其他类型的晶体管。</p><p>伴随摩尔定律的发展，集成电路的晶体管数量不断增加，对功耗的要求也不断增加。基于低功耗、低成本的优势，CMOS 工艺成为半导体领域的主流。今天 95% 以上的集成电路芯片都是基于 CMOS 工艺制造的。</p><h2 id="七平面晶体管与-finfet" tabindex="-1">七、平面晶体管与 FinFET <a class="header-anchor" href="#七平面晶体管与-finfet" aria-label="Permalink to &quot;七、平面晶体管与 FinFET&quot;">​</a></h2><p>CMOS 工艺在发展过程中也遇到过障碍，并不是一帆风顺的。</p><p>早期晶体管主要基于<strong>平面型晶体管</strong>（PlanarFET）的结构。随着晶体管体积不断缩小，栅极长度越做越短，源极和漏极之间的距离逐渐靠近，会存在明显的短沟道效应，制造过程中的偏差对它的影响也非常大。</p><p>当制程小于 20 nm 时，MOSFET的栅极难以关闭电流通道，躁动的电子无法被阻拦，漏电现象屡屡出现，功耗也随之变高，性能也受到显著影响。</p><p>为了解决这个问题，1999年，美籍华裔科学家胡正明教授，发明了鳍式场效应晶体管(FinFET)。</p><p>相比PlanarFET的平面设计，FinFET直接变成了3D的立体结构。它的电流通道变成了像鱼鳍一样的薄竖片，三面都用栅极包夹起来，这样就有了比较强大的电场，提升了控制通道的效率，可以更好地控制电子能否通过。</p><h2 id="八gaafet-与-mbcfet" tabindex="-1">八、GAAFET 与 MBCFET <a class="header-anchor" href="#八gaafet-与-mbcfet" aria-label="Permalink to &quot;八、GAAFET 与 MBCFET&quot;">​</a></h2><p>技术节点继续演进，到 5 nm 之后，FinFET 又不太合适了：原先控制力很强，但受短沟道效应影响，控制能力也弱化了，于是又提出一种新的结构。</p><p>于是，5 nm 以下有了 GAAFET（环绕式栅极晶体管）。相比 FinFET，GAAFET 把栅极和漏极从鳍片又变成了一根根的&quot;小棍子&quot;，垂直穿过栅极。从最上面这一根棍子来看，对整个沟道的控制从三面接触变成了彻底的四面接触，栅极对沟道的控制能力又进一步提高。</p><p>GAAFET 主要是台积电在使用。三星对GAAFET结构又做了一个改进，是 GAA形式-MBCFET（多桥-通道场效应管）：采用多层纳米片替代 GAA 中的纳米线，更大宽度的片状结构增加了接触面，在保留所有原有优点的同时，还实现了复杂度最小化。</p><p>正是这种结构的不断演进，保证了 CMOS 工艺和集成电路的发展，摩尔定律能够继续延续下去。</p><h2 id="九pdk-是什么" tabindex="-1">九、PDK 是什么 <a class="header-anchor" href="#九pdk-是什么" aria-label="Permalink to &quot;九、PDK 是什么&quot;">​</a></h2><p>PDK 的英文全称是 Process Design Kit，也就是工艺设计数据包、工艺设计套件。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794470661190-42625ec0-c85d-442e-9329-cf8844579989.svg" alt="PDK 向外连到器件模型、标准单元库等分支"></p><p><em>PDK 包含器件模型、标准单元库、IP 库等。</em></p><p>PDK 主要包含两大类：一类是器件模型，比如 SPICE 模型库；另一大类跟版图相关，包括版图基础工艺库、设计规则，以及版图检查工具，这两块跟模拟比较相关。还有标准单元库，主要跟数字关联；另外一些文本类的、IP 库，平时可能接触不多。</p><p>PDK 是芯片生产厂家Foundry厂、Fab厂提供给 IC 设计公司使用的、有关制造工艺的模型和 EDA 工具支持的整个数据包。包含 IC 设计前端到后端的所有数据支持，是连接 IC 设计公司和制造公司之间的数据平台。</p><p>目前模拟设计的工具平台主流还是 Cadence，所以，整个 PDK 包主要提供的还是基于 Cadence 这套 flow 的 EDA 工具支持流程。</p><p>同样一个台积电 28 nm 的 PDK 包，既要支持 Cadence 的环境，也要支持其他家，比如 Synopsys、Mentor 或者华大。不同家 EDA 工具在解析上有差异，底层包括 SPICE 器件模型库在内，可能需要对底层的参数接口或者模型参数做一些调整。所以不同平台上的 PDK 还是会有差异。</p><h2 id="十器件模型与设计规则" tabindex="-1">十、器件模型与设计规则 <a class="header-anchor" href="#十器件模型与设计规则" aria-label="Permalink to &quot;十、器件模型与设计规则&quot;">​</a></h2><p>PDK 里的器件模型主要是 SPICE 模型，有源的是晶体管的模型，无源的包括电阻、电容、电感的器件模型。</p><p>Foundry 厂会把模型和测试做一些对比，没有问题就把相应的模型发布出来。</p><p>本质上 SPICE 模型就是一个仿真程序，里面定义了很多模型参数去表征模型的行为特性。我们主要是调用这个程序去做电路的仿真分析。</p><p>设计规则也是 PDK 的一个重要部分。电路设计最终要通过绘制成版图、生成 GDS 之后，交给厂家去做生产。</p><p>设计规则会对版图的层次做定义，包括版图的几何形状，以及 GDS 里的一些效应：ESD、Latch up 防护效应、天线效应规则、电流密度效应规则，还有一些应力相关的保护规则。</p><p>版图工艺库里也会提供一些基本的绘制版图所用到的 PCELL、版图显示的定义，GDS格式转换映射文件、抽象结构的单元版图、固定结构的器件版图。</p><p>作为版图工程师，除了要能绘制版图、了解这些设计规则，还要熟练运用版图检查工具。一般基于设计规则，对版图做 DRC、LVS 检查，还会做 ERC 检查，以及寄生参数抽取这类检查。</p><h2 id="十一pdk-的主要内容" tabindex="-1">十一、PDK 的主要内容 <a class="header-anchor" href="#十一pdk-的主要内容" aria-label="Permalink to &quot;十一、PDK 的主要内容&quot;">​</a></h2><p><strong>工艺库</strong>，也叫基础库，是 Foundry 厂提供的电路、版图设计基础信息集合。不管做电路仿真还是版图设计，都要调用工艺库。它包含电路设计需要的 SPICE 器件模型和仿真数据 model、器件描述格式 CDF 等内容，也包含版图设计所需要的 PCELL 基础单元器件版图。实际上所有的器件模型信息都在工艺库里能找到。</p><p><strong>数字标准单元库</strong>，是工艺厂提供的已经设计好的数字标准单元电路和版图，可以提高 IC 设计公司的效率，大规模应用在 APR（数字版图的自动布局布线）项目里。</p><p><strong>标准单元库</strong>一般基于最小面积的考虑去设计，尺寸、版图绘制都基于最低标准，所以面积集成度可以做得比较高。但对模拟版图来说，有些地方需要自己画数字单元：模拟这边也会涉及到一些简单的数字控制逻辑，基于模拟电路设计可靠性的考虑，可能需要自己做一些定制处理，就不直接调用标准单元库了。</p><p><strong>IP 库</strong>在 PDK 里其实很少看到。IP 是已经成型的、具有特定功能的电路模块。对一家IC设计公司来说，SoC 里面的模块分得很多，所有模块都自己做会带来很大的人力成本；如果这个公司不具备某方面能力的，就需要从外部购买这个 IP。</p><p>除了 PDK 厂商提供 IP，像 Cadence、Synopsys 这些公司，一方面做 EDA 工具，另一方面也会做大量 IP。</p><p>有些公司用某家公司的 EDA 工具的需求没那么高，但对这家公司的 IP 反而是硬性要求。</p><p>所以，通过推 IP 也可以进一步推动工具的使用，因为 IP 一般是基于公司自己的平台去做设计的，别人要用某家公司的 IP，就需要同步用这家公司的平台做设计。</p><p>IP 的成本比较高，需要花钱购买，所以一般在 PDK 里是看不到 IP 的。</p><p><strong>设计规则文件</strong>跟版图相关，是版图设计上必须遵守的原则，按照符合工艺厂最低标准要求总结出来的文件。</p><p>比如版图里两条走线之间的间距最低标准是多少、线间距最低要到多少。并不是走得越宽越好，一般情况下都按最小标准走线。但对模拟电路来说，对寄生的要求会限制它对最低标准的使用，所以经常需要结合电路仿真的性能，去界定到底走多大的标准比较合适一些。</p><p>设计规则文件包含版图层次的定义、几何图形规则等物理上的定义，同时包含天线效应、电流密度规则、ESD、Latch up 等电学特性的可靠性设计要求。</p><p>主要是两块：</p><p>一块是 design rule，设计规则文件，主要用于查找 grid、层次定义、层次画法和间距；</p><p>另一块是 Electrical Specifications，电学特性文件，给出具体的工艺参数及其结果抽象出的电学参数，是电路与系统设计、模拟的依据，Layout 主要用来查找电阻值、过电流能力等。</p><h2 id="十二设计规则检查文件与其他重要文件" tabindex="-1">十二、设计规则检查文件与其他重要文件 <a class="header-anchor" href="#十二设计规则检查文件与其他重要文件" aria-label="Permalink to &quot;十二、设计规则检查文件与其他重要文件&quot;">​</a></h2><p>设计规则检查文件来源于 PDK 提供的设计规则。</p><p>模拟里用得比较多的工具，一般会针对自己工具的平台去开发 DRC、LVS 的规则文件。</p><p>DRC 主要检查版图的物理特性是否符合 design rule 要求。</p><p>LVS 是电路与版图一致性的检查，方法是从版图中提取数据转换成网表，和电路转换的网表做数据对比，把不一样的地方通过工具显示出来，方便 layout 改动。</p><p>Ant rule 用于检查天线效应是否满足设计要求，是可靠性设计中的一种。</p><p>LPE 用来提取后仿真版图数据。对已设计的版图提取各种器件、它们的连接关系，以及各种寄生电容和电阻，把提取出的器件、连接关系和寄生参量作为电路模拟的输入数据，再次做电路模拟仿真，估计寄生参量对电路性能的影响。这也就是后仿真的东西，用来评估版图走线的寄生对电路性能的影响。</p><p>其他重要文件还有 Techfile 文件、display.drf 文件、layermap 文件，这些都跟版图设计和验证强相关。</p><p>Techfile 包含的信息最全面，涵盖整个版图设计跟验证、基本的电学规则、图层信息、色彩定义，还有基础 PCell 定义等，可以理解成整个基础库浓缩的语言格式。</p><p>display.drf 主要用来定义层次和工具中各种图形的颜色。layermap 是导出、导入 GDS 的映射文件，定义每层 layer 对应的 GDSII 码。</p><p>还有 Cadence 环境里适配的一些文件，包括 cds.lib、.cdsinit、.cdsenv。</p><h2 id="十三virtuoso-的-librarycellview" tabindex="-1">十三、Virtuoso 的 Library、Cell、View <a class="header-anchor" href="#十三virtuoso-的-librarycellview" aria-label="Permalink to &quot;十三、Virtuoso 的 Library、Cell、View&quot;">​</a></h2><p>Virtuoso 打开以后有一个 Library Manager 窗口，里面有三个部分：Library、Cell、View。</p><p>做电路设计，包括库的管理、电路的新建，以及版图设计，都是在这个里面新建 Cell 或者 View 来操作。</p><h2 id="十四芯片制造全流程" tabindex="-1">十四、芯片制造全流程 <a class="header-anchor" href="#十四芯片制造全流程" aria-label="Permalink to &quot;十四、芯片制造全流程&quot;">​</a></h2><p>整个工序大概分为硅片制造、晶圆制造、芯片封装和芯片测试。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794496791198-c9c7ee36-7881-46a5-9010-0f25c5152f04.svg" alt="从硅片制造到交付客户的全流程"></p><p><em>涵盖硅片制造、芯片设计、晶圆制造与封测交付。</em></p><p>硅片制造这边，Foundry厂拿到硅片以后，进行一系列的工序，也就是晶圆制造。晶圆制造之后，在上面形成一片一片的裸片，再拿给芯片封装厂做切割、封装，封装完再交给测试厂家做芯片测试和老化检验，测试没问题之后交付给客户。</p><p>芯片设计在整个流程里处于什么位置：</p><p>电路设计、芯片设计最终都是生成一个 GDS 文件提供给厂家。</p><p>厂家根据 GDS 的图层信息，生成各种各样的光罩掩膜板，也就是俗称的 mask。每一层 mask 代表制造的一道工序，mask 越多，整个制造成本就越高。</p><p>基于 mask 的图层信息，Foundry厂会通过光刻机做曝光处理，把这些图层信息在硅片上一层层刻出来。如果提供的图层信息有 100 层 mask，就要经过 100 次曝光制造，中间不停经过刻蚀、离子注入这些流程，最终在晶圆上形成成千上万的裸片。</p><p>裸片还要拿给封装厂，一颗一颗切割下来。裸片不便于存储和运输，也很容易损坏，所以一般还要经过封装处理；封装之后做芯片测试，最后交给客户。</p><p>晶圆制造的厂家自己一般很少制造硅片，硅片一般通过第三方提供。</p><h2 id="十五idm-与-fabless-两种制造模式" tabindex="-1">十五、IDM 与 Fabless 两种制造模式 <a class="header-anchor" href="#十五idm-与-fabless-两种制造模式" aria-label="Permalink to &quot;十五、IDM 与 Fabless 两种制造模式&quot;">​</a></h2><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794496213401-cee6ef48-6f28-420a-ab5b-a7adf5feb0ae.svg" alt="IDM 与 Fabless 的模式对比"></p><p><em>IDM 自己做全流程，Fabless 制造封测外包。</em></p><p>业内一般有两种模式，一种是 IDM 模式，另外一种是 Fabless 模式。</p><p>IDM 模式是芯片的设计、生产、封装和测试都是自己做的。比如英特尔这样的大厂，比如武汉的长江存储，他们设计的内存芯片，自己设计、生产、封装，工艺也是自己提供，整个流程都自己走完。</p><p>大多数企业用 Fabless 模式，因为 IDM 成本会比较高：自己建晶圆厂，特别是先进工艺，建一个晶圆厂至少是几十上百亿的规模。</p><p>Fabless 公司主要负责芯片的设计、研发和销售，晶圆制造交给台积电这类 Foundry 做生产，封装测试也交给封测厂完成，只参与设计和销售的环节，成本相对低一点。</p><p>但对要求比较高的定制化芯片，Fabless的工艺可能只能用通用的，IDM 模式的工艺产线则可以根据实际状态不停调整，所以适合需要定制化的产品，比如功率器件；这种情况如果是基于通用工艺去做，那做出来的产品就缺乏竞争力。</p><h2 id="十六射频收发系统" tabindex="-1">十六、射频收发系统 <a class="header-anchor" href="#十六射频收发系统" aria-label="Permalink to &quot;十六、射频收发系统&quot;">​</a></h2><p>通信领域的射频收发 SoC 芯片主要用在 5G 基站的射频收发系统，规格是 2T2R，也就是两通道发射和两通道接收。</p><p>系统除发射和接收链路外，还需要 PLL 给整个系统提供时钟。里面还会涵盖一些数字的部分，比如会有一些数字校准技术，也包括提供一些数字控制。另外还有 8×16 Gbps 的 SerDes 接口和 SerDes 模块，以及 GPIO、SPI 这种外设接口。</p><p>把所有外围都集成进这一颗 SoC 是理想方案，但 CMOS 工艺有它的局限：</p><p>功放、LNA 这类电路用 CMOS 实现，性能会比较弱。</p><p>以 PA 为例，要实现 30 dBm 的输出功率，在 CMOS 工艺下可能要很大的功耗，推出来的功率也很低，或者整个系统的性能就会很差。</p><p>所以目前主流采用 SoC 加片外射频模组的形式。</p><p>PA、LNA 这类改用化合物工艺实现，性能更高，代价是增加整个系统的成本，集成度也没有那么高。</p><h2 id="十七发射与接收链路的信号流程" tabindex="-1">十七、发射与接收链路的信号流程 <a class="header-anchor" href="#十七发射与接收链路的信号流程" aria-label="Permalink to &quot;十七、发射与接收链路的信号流程&quot;">​</a></h2><p>以发射来说，数字提供编码好的数字基带信号，一般是调制信号，频率 0 到 100 MHz，里面有数字基带调制好的有用信息。</p><p>通过 DAC 把数字信号转换成模拟信号。转换过程中会存在一些谐波，后面一般接一个滤波器，对谐波信号做滤波处理。</p><p>滤波之后是比较干净的信号，再通过一个混频器。混频器的功能是把频谱搬移，相当于一个乘法器，在频域上把 0 到 100 MHz 的信号通过本振载波加载到高频上去。</p><p>加载过来之后，这个地方会引入一些非线性的东西，信号质量变差，所以后面也会做一些滤波处理。射频信号再经过一些放大处理之后，通过 PA 对信号进一步放大，达到系统要求的输出功率，然后通过天线把调制之后的信号发射出去。</p><p>接收端同样是通过天线接收射频信号，比如一个 5.1 GHz 的信号，经过远距离传输之后，信号通常比较微弱，前端的 LNA 低噪声放大器对整个信号做放大，尽量不引入噪声。放大之后，通过内部的一些模块做增益调整或者滤波处理，再传递给下混频器做解调：一个 5.1 GHz 的信号，通过 5 GHz 的本振载波，把整个信号解调到 100 MHz 的低频上去。</p><p>解调过程会对信号引入一些非线性的因素，解调出来的信号质量不一定那么好，后面需要滤波器或者增益调节模块，对整个信号再做调整，然后传递给 ADC。ADC 把连续的模拟信号通过采样转换成数字信号，再交给数字系统做解码处理。</p><p>整个环路从发射到接收，完成信息的交互。</p><h2 id="十八哪些地方需要场仿真" tabindex="-1">十八、哪些地方需要场仿真 <a class="header-anchor" href="#十八哪些地方需要场仿真" aria-label="Permalink to &quot;十八、哪些地方需要场仿真&quot;">​</a></h2><p>整个系统里跟场仿真强相关的，基本上以混频器为界。</p><p>从发射来看，PA 往前推，一直推到混频器这一块，涉及高频信号的传递。这一块如果用 RC 工具抽取，不能满足要求，需要用到场仿真工具，对混频器到整个 PA 这一块做场仿真，真实表现走线的寄生状态。</p><p>接收也是类似的，从 LNA 到前端的电阻之类的模块，一直到混频器这一块，都是高频信号的传递，也就是场仿真需要用到的地方。</p><p>还有一块是 PLL 锁相环。时钟本身就是一个高频的东西，不管上变频还是下变频，都通过时钟提供载波，所以时钟电路这一块也是场仿真领域里的一个大头。时钟非常敏感，对整个系统性能影响大：它产生的相噪、时钟抖动和幅度，对调制解调的质量影响会比较大。锁相环是一个系统，VCO 是锁相环里面的一个子模块，锁相环里会大量用到场仿真工具去做信号仿真。</p><p>系统要支持很多模式，里面会涉及多个时钟的交互。芯片规格很大，但通常并不会每个通道采用一个时钟，可能多个通道共用一个时钟，导致时钟走线在整个系统里非常长：时钟放在上方中间部位，要支撑最左边的TX1和最右边的TX2通道，走线可能达到几千微米级别。对这种时钟走线，场仿真的要求会比较多。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794539142338-5b285e74-29c9-493d-bcbb-9a73c9e27357.svg" alt="2T2R 芯片版图分区示意"></p><p><em>RF LO PLL 位于上方中间，两侧是收发通道。</em></p><h2 id="十九系统指标与模块拆解" tabindex="-1">十九、系统指标与模块拆解 <a class="header-anchor" href="#十九系统指标与模块拆解" aria-label="Permalink to &quot;十九、系统指标与模块拆解&quot;">​</a></h2><p>系统级的指标跟模块级的还是有差异：</p><p>整个系统不是一个人完成的，设计上相对复杂，设计阶段会把整个系统拆解到不同的模块上，不同模块有不同的指标，去衡量这个模块能否满足系统设计和链路的指标要求。</p><p>即使最终所有模块都设计好了，还是要把所有模块串联起来，做整个电路的串联仿真，去对比整个系统的指标要求。</p><p>RX 这边主要关注带宽，比如 RF BW 是 200 MHz，也就是基带调制信号的带宽。这类链路支持的制式非常多，基站里早期是 2G，后面随着技术演进变成 3G、4G、5G，5G 才支持到 200 MHz；早期可能不需要支持到 200 MHz，200 MHz 就是它最大的带宽能力。一般能实现 200 MHz 的能力，就认为比较小的带宽比如 100 MHz 或者 20 MHz 也能支持；但从严谨、全面的验证角度，每一种带宽支持都需要充分验证。</p><p>还有 SFDR 这类杂散指标，以及支持的频段范围。2G、3G、4G、5G 的频段范围不一样，国内跟国外也有差异，所以要多涵盖一些，比如从 GSM 这种模式 400 MHz 左右一直到 6 GHz，可能还需要支持一些专网。时钟支持的范围很宽，从 400 MHz 到 6 GHz。</p><p>同一个电路去实现这么宽的频率范围，性能会发生很大的变化。正常情况下会有很多套结构：一个通道里看到的电路可能是这一套，但它支持的范围有限，比如只能 400 MHz 到 1 GHz；要支持到 6 GHz，同样的电路可能要做 3 套，每一套支持的频率范围有差异。所以看上去整个电路模块好像比较少，但支持这么大的带宽之后，电路规格其实比较大，对场仿真的需求也多：不同频率下的匹配、电路模块要求都不一样，都要对不同模块做调试。</p><p>RX 这边重点关注 NF、IIP3、IIP2 这些指标。TX 那边跟它是反向的，也关注 RF BW；发射信号需要满足通信协议的要求，比如 LTE 的支持、ACLR，还有 EVM 这类指标，比如 EVM 在 2.6 GHz 需要达到一个指标，以及 TDD/FDD 情况下的功耗要求。</p><p>整个链路可以拆解到具体的模块级别。电路设计上拿到系统指标之后，一般的逻辑是对它做建模，把功能模块逐个做功能拆解，得到每个模块的设计指标。RX 整个电路需要完成的指标，到 LNA 这一级就会有相应的指标做约束。每个模块完成相应的设计之后，最终要把整个链路连在一起做联调，去满足整个链路的指标特性。</p><h2 id="二十有源器件与场仿真" tabindex="-1">二十、有源器件与场仿真 <a class="header-anchor" href="#二十有源器件与场仿真" aria-label="Permalink to &quot;二十、有源器件与场仿真&quot;">​</a></h2><p>混频器到功放那个阶段用场仿真。</p><p>混频器属于有源器件，有比较强的非线性，正是因为这个非线性才有频谱搬移的功能。</p><p>有源器件的仿真是一种基于类似信号的行为模型，比如 ADS 用谐波平衡（Harmonic Balance）的方法，它并不是场仿真工具；</p><p>功放衡量线性度、3 dB 压缩点这些指标，也是一种信号模型，并不直接涉及麦克斯韦方程组的求解。</p><p>麦克斯韦方程组是线性的，对非线性可能没有直接的获取。</p><p>那么真正在混频器、功放这种非线性，甚至 PLL 锁相环里面的有源器件部分，场仿真工具怎么样有直接的应用？</p><p>所谓的场仿真，主要还是针对后仿真阶段的应用。它里面还是会调用有源管的 SPICE model 去做仿真，但涉及有源的一些走线、模块之间的连线，更多的是说无源的金属连线的寄生去做场。</p><p>低频跟射频的区别：</p><p>低频主要通过 RC 工具去抽，只对金属做 RC 抽取；</p><p>射频里面对金属还要做电感的抽取，也就是 RLC。</p><p>有源的部分在电路里都会扣出来，不会直接把有源带到里面整个去跑一个场，一是工具不一定支持，二是涉及模型问题，可能根本没办法仿真。</p><p>所以，场仿真是把里面的连线通过场去做一个 SNP 抽取，最后把这个 SNP 再结合有源的 SPICE 模型，一起做仿真，这样是一个比较完整的射频仿真。相当于只是仿了无源走线的部分。</p><p>Sub-6G 以下，什么部分用 RLC、什么部分用电磁场，有没有一个相对明确的评判标准？</p><p>Sub-6G 以下的主流做法：</p><p>即使在射频，比如做一个功放、PA driver 或者 LNA，有源部分之间的连线，比如一个晶体管有多个单元、它们之间比较短的互连线，还是用抽 RC 的工具，比如 Calibre 这类，对连线做 RC 抽取；只对电感、电容这类无源器件，包括它们的连线才用场仿真。</p><p>但毫米波应用领域，频率更高，晶体管之间的连线虽然看起来比较短，对毫米波频段来说也可能有比较大的寄生电感，所以毫米波频段里也需要把有源管之间的连线，通过打端口的方式跟有源部件的端子连接起来，场仿真会深入到贴近晶体管端子的这一侧。</p><p>频率越高，仿真的电路端子会非常多：</p><p>有源管一个单元可能对应四个端子，要是有几十上百个单元，就可能要打几百个端子，构造建模比较麻烦。</p><p>Sub-6G 影响可能比较小，从工作量来看比较麻烦，一般就不这么做；</p><p>但毫米波不这么做，仿真性能差异会比较大，还得必须这么做，所以会涉及打很多端子，把有源的连线也考虑进去做场仿真。</p><p>毫米波这种有源部分的互连，设计一般由 Fabless 工程师做，还是 Foundry 里会直接参与设计？</p><p>一般都是 Fabless 自己做的。晶圆厂只关心符不符合设计规则，不关心怎么走，也不会给建议，需要设计师自己判断到底怎么走更合适。所以高频模块的 layout 一般都是设计师自己画；大部分 layout 是由版图工程师完成的，但频率特别高的模块，版图工程师只会按规则去设计版图，不会考虑寄生到底有多大、符不符合预期。设计师有相关经验的，会考虑高频输入信号怎么走、电源地怎么布局更合理，减小寄生对整个芯片性能的影响。特别是单片前端这类，更依赖设计师的设计经验。</p><p>有源扣出来单独建模，无源部分用场仿真，最后用 Harmonic Balance 兜起来仿真。现在频率越来越快，有源器件越来越多，扣出来相当于在整个版图上留下很多空洞，这些空洞对无源器件的场仿真会不会有很大影响？</p><p>Sub-6G一般不这么做；接触到的案例里，即使是成片的版图，也没有把端口打到跟晶体管贴得那么近的水平，会做一些简化：</p><p>一个晶体管有若干端子，可能有一条总线，直接在总线上打端口，而不是在总线上再引出每个端子的连线、在连线末端打端口，建模本身会有简化。</p><p>空洞的影响：</p><p>因为仿真的是成片的，空洞也不是一个一个的小空洞，会留下一整片的空洞。</p><p>总线走线的层次稍微高一点；如果直接跟晶体管区对接，要往下跳一些金属层，可能跳到很底层，金属层数很多，底层金属宽度非常窄，可能只有十几纳米或者几纳米，剖分的时候参数不好设；即使这么做了，仿真效果也不一定好。</p><p>所以一般也会做一些简化，仿真效率更高，工作量也更小。</p>',211)])])}const u=a(o,[["render",d]]);export{P as __pageData,u as default};
